/*!
 * Basketball Widget — 街機投籃浮層
 * 用法：<script src="basketball-widget.js"></script>
 * 會自動把籃框、瞄準器、籃球、計分 HUD 注入到頁面
 * 零依賴、單檔
 */
(function () {
  if (window.__BASKETBALL_WIDGET_LOADED__) return;
  window.__BASKETBALL_WIDGET_LOADED__ = true;

  // ====== 籃球圖（base64，會在 build 時注入） ======
  var BALL_URL = "data:image/png;base64,";

  // ====== 注入 CSS ======
  var css = [
    '#bbw-hud{position:fixed;top:16px;left:16px;z-index:2147483600;background:rgba(0,0,0,.6);padding:8px 16px;border-radius:12px;border:1px solid rgba(255,255,255,.18);backdrop-filter:blur(6px);pointer-events:none;font-family:-apple-system,"Noto Sans TC",sans-serif;color:#fff;}',
    '#bbw-hud .l{font-size:10px;letter-spacing:3px;color:#ffd84a;}',
    '#bbw-hud .s{font-size:24px;font-weight:900;line-height:1.1;}',
    '#bbw-toast{position:fixed;left:50%;top:28%;transform:translateX(-50%) scale(.5);opacity:0;font-size:64px;font-weight:900;color:#ffd84a;text-shadow:0 6px 0 #b8860b,0 8px 24px rgba(0,0,0,.5);pointer-events:none;z-index:2147483646;transition:transform .35s cubic-bezier(.34,1.56,.64,1),opacity .35s;white-space:nowrap;font-family:-apple-system,"Noto Sans TC",sans-serif;}',
    '#bbw-toast.show{transform:translateX(-50%) scale(1);opacity:1;}',
    '#bbw-ball{position:fixed;left:0;top:0;width:36px;height:36px;border-radius:50%;cursor:pointer;z-index:2147483647;user-select:none;-webkit-user-drag:none;will-change:transform;background:url("' + BALL_URL + '") center/contain no-repeat;filter:drop-shadow(0 6px 8px rgba(0,0,0,.5));}',
    '#bbw-ball:hover{filter:drop-shadow(0 0 8px #ffd84a) drop-shadow(0 6px 8px rgba(0,0,0,.5));}',
    '#bbw-hoop{position:fixed;left:0;top:0;z-index:2147483644;pointer-events:none;will-change:transform;}',
    '#bbw-hoop .bd{position:absolute;width:4px;height:64px;background:linear-gradient(90deg,rgba(255,255,255,.92),rgba(255,255,255,.7));border:2px solid #ddd;border-radius:4px;box-shadow:0 6px 16px rgba(0,0,0,.4);}',
    '#bbw-hoop .bd:after{content:"";position:absolute;left:50%;top:28%;width:18px;height:12px;transform:translate(-50%,0);border:2px solid #d22;border-radius:2px;}',
    '#bbw-hoop .rim{position:absolute;width:60px;height:4px;background:linear-gradient(180deg,#ff5a1f,#b8260a);border-radius:4px;box-shadow:0 4px 8px rgba(0,0,0,.4);}',
    '#bbw-hoop .net{position:absolute;width:60px;height:26px;background:repeating-linear-gradient(60deg,rgba(255,255,255,.85) 0 1px,transparent 1px 8px),repeating-linear-gradient(-60deg,rgba(255,255,255,.85) 0 1px,transparent 1px 8px);clip-path:polygon(0 0,100% 0,86% 100%,14% 100%);opacity:.9;transform-origin:top center;}',
    '#bbw-hoop .net.swish{animation:bbw-swish .35s ease;}',
    '@keyframes bbw-swish{0%{transform:scaleY(1);}40%{transform:scaleY(1.4);}100%{transform:scaleY(1);}}',
    '#bbw-aim{position:fixed;left:0;top:0;width:110px;height:14px;transform-origin:0% 50%;z-index:2147483643;pointer-events:none;will-change:transform;}',
    '#bbw-aim .bar{width:100%;height:100%;background:linear-gradient(90deg,rgba(255,216,74,.95) 0%,rgba(255,216,74,.95) 40%,rgba(255,216,74,.5) 70%,transparent 100%);border-radius:7px;box-shadow:0 0 12px rgba(255,216,74,.7);}',
    '#bbw-aim .tip{position:absolute;right:-2px;top:50%;width:0;height:0;transform:translateY(-50%);border-left:14px solid #ffd84a;border-top:10px solid transparent;border-bottom:10px solid transparent;filter:drop-shadow(0 0 6px rgba(255,216,74,.7));}',
    '#bbw-aim.hidden{opacity:0;}',
    '#bbw-dot{position:fixed;left:0;top:0;width:18px;height:18px;margin-left:-9px;margin-top:-9px;border-radius:50%;border:3px dashed rgba(255,255,255,.55);z-index:2147483642;pointer-events:none;}',
  ].join('\n');

  var style = document.createElement('style');
  style.id = 'bbw-style';
  style.textContent = css;
  document.head.appendChild(style);

  // ====== 注入 DOM ======
  var hud = h('div', { id: 'bbw-hud' }, '<div class="l">SCORE</div><div class="s" id="bbw-score">0</div>');
  var toast = h('div', { id: 'bbw-toast' }, 'SCORE!');
  var hoop = h('div', { id: 'bbw-hoop' }, '<div class="bd"></div><div class="rim"></div><div class="net"></div>');
  var aim = h('div', { id: 'bbw-aim' }, '<div class="bar"></div><div class="tip"></div>');
  var dot = h('div', { id: 'bbw-dot' });
  var ball = h('div', { id: 'bbw-ball' });

  [hud, toast, hoop, aim, dot, ball].forEach(function (el) { document.body.appendChild(el); });

  var scoreEl = document.getElementById('bbw-score');
  var netEl = hoop.querySelector('.net');
  var backboardEl = hoop.querySelector('.bd');
  var rimEl = hoop.querySelector('.rim');

  function h(tag, attrs, html) {
    var el = document.createElement(tag);
    if (attrs) for (var k in attrs) el.setAttribute(k, attrs[k]);
    if (html) el.innerHTML = html;
    return el;
  }

  // ====== 物理 ======
  var SIZE = 36, RADIUS = SIZE / 2;
  var GRAVITY = 0.6, AIR = 0.998;
  var BOUNCE_WALL = 0.6, BOUNCE_FLOOR = 0.55, BOUNCE_RIM = 0.55, BOUNCE_BOARD = 0.65;
  var GND_FRICTION = 0.9, SPIN = 0.55, MAX_V = 60;

  var x = 0, y = 0, vx = 0, vy = 0, rot = 0, vrot = 0;
  var inFlight = false, score = 0;

  // 籃框
  var RIM_W = 60, RIM_H = 4, BOARD_W = 4, BOARD_H = 64;
  var board = { x: 0, y: 0, w: 0, h: 0 };
  var rimLeft  = { x: 0, y: 0, r: 3 };
  var rimRight = { x: 0, y: 0, r: 3 };
  var scoreZone = { x1: 0, x2: 0, y: 0 };

  // 發球
  var shooter = { x: 0, y: 0 };
  var AIM_MIN = 100, AIM_MAX = 175, AIM_SPEED = 1.4;
  var aimAngle = AIM_MIN, aimDir = 1, aiming = true;
  var SHOOT_POWER = 23;
  var canScore = true, touchedHoopSinceShot = false;

  function layout() {
    var W = window.innerWidth, H = window.innerHeight;
    var cL = 8, cT = H - BOARD_H - 60;
    hoop.style.transform = 'translate(' + cL + 'px,' + cT + 'px)';
    backboardEl.style.left = '0px'; backboardEl.style.top = '0px';
    board = { x: cL, y: cT, w: BOARD_W, h: BOARD_H };
    var rimTop = BOARD_H * 0.5;
    rimEl.style.left = BOARD_W + 'px'; rimEl.style.top = rimTop + 'px';
    netEl.style.left = BOARD_W + 'px'; netEl.style.top = (rimTop + RIM_H) + 'px';
    rimLeft  = { x: cL + BOARD_W + 3,         y: cT + rimTop + RIM_H/2, r: 3 };
    rimRight = { x: cL + BOARD_W + RIM_W - 3, y: cT + rimTop + RIM_H/2, r: 3 };
    scoreZone = { x1: rimLeft.x + rimLeft.r + 2, x2: rimRight.x - rimRight.r - 2, y: rimLeft.y };
    shooter = { x: W - 90, y: H - 100 };
    dot.style.transform = 'translate(' + shooter.x + 'px,' + shooter.y + 'px)';
  }

  function reset() {
    x = shooter.x - RADIUS; y = shooter.y - RADIUS;
    vx = vy = vrot = 0; rot = 0;
    inFlight = false; aiming = true;
    touchedHoopSinceShot = false;
    aim.classList.remove('hidden');
  }

  function render() {
    ball.style.transform = 'translate(' + x + 'px,' + y + 'px) rotate(' + rot + 'deg)';
    if (aiming) aim.style.transform = 'translate(' + shooter.x + 'px,' + shooter.y + 'px) rotate(' + (-aimAngle) + 'deg)';
  }

  function clampV() {
    if (vx >  MAX_V) vx =  MAX_V; if (vx < -MAX_V) vx = -MAX_V;
    if (vy >  MAX_V) vy =  MAX_V; if (vy < -MAX_V) vy = -MAX_V;
  }

  function collideCircle(c) {
    var bx = x + RADIUS, by = y + RADIUS;
    var dx = bx - c.x, dy = by - c.y, d = Math.hypot(dx, dy), m = RADIUS + c.r;
    if (d < m && d > 0) {
      var nx = dx/d, ny = dy/d, o = m - d;
      x += nx*o; y += ny*o;
      var dot = vx*nx + vy*ny;
      vx = (vx - 2*dot*nx) * BOUNCE_RIM;
      vy = (vy - 2*dot*ny) * BOUNCE_RIM;
      vrot = vx * SPIN * 1.5;
      return true;
    }
    return false;
  }
  function collideRect(r) {
    var bx = x + RADIUS, by = y + RADIUS;
    var cx = Math.max(r.x, Math.min(bx, r.x + r.w));
    var cy = Math.max(r.y, Math.min(by, r.y + r.h));
    var dx = bx - cx, dy = by - cy, d = Math.hypot(dx, dy);
    if (d < RADIUS && d >= 0) {
      var nx, ny;
      if (d === 0) { nx = 1; ny = 0; } else { nx = dx/d; ny = dy/d; }
      var o = RADIUS - d;
      x += nx*o; y += ny*o;
      var dot = vx*nx + vy*ny;
      vx = (vx - 2*dot*nx) * BOUNCE_BOARD;
      vy = (vy - 2*dot*ny) * BOUNCE_BOARD;
      vrot = vx * SPIN * 1.5;
      return true;
    }
    return false;
  }

  function showToast(text, color) {
    toast.textContent = text;
    toast.style.color = color || '#ffd84a';
    toast.classList.remove('show'); void toast.offsetWidth;
    toast.classList.add('show');
    setTimeout(function(){ toast.classList.remove('show'); }, 700);
  }

  function checkScore(prevY) {
    if (!canScore) return;
    var bx = x + RADIUS, prevC = prevY + RADIUS, curC = y + RADIUS;
    if (vy > 0 && prevC <= scoreZone.y && curC > scoreZone.y) {
      if (bx > scoreZone.x1 && bx < scoreZone.x2) {
        var swish = !touchedHoopSinceShot;
        score += swish ? 3 : 2;
        scoreEl.textContent = score;
        showToast(swish ? 'SWISH! +3' : 'SCORE! +2', swish ? '#7df' : '#ffd84a');
        netEl.classList.remove('swish'); void netEl.offsetWidth; netEl.classList.add('swish');
        canScore = false;
        setTimeout(function(){ canScore = true; }, 800);
      }
    }
  }

  function shoot() {
    if (!aiming) return;
    aiming = false;
    aim.classList.add('hidden');
    inFlight = true;
    var rad = aimAngle * Math.PI / 180;
    vx =  Math.cos(rad) * SHOOT_POWER;
    vy = -Math.sin(rad) * SHOOT_POWER;
    vrot = vx * SPIN * 2;
    touchedHoopSinceShot = false;
  }

  var restFrames = 0;
  function maybeReset() {
    var W = window.innerWidth, H = window.innerHeight;
    var onFloor = (y + SIZE) >= H - 1;
    var slow = Math.abs(vx) < 0.5 && Math.abs(vy) < 0.5;
    if (inFlight && onFloor && slow) { restFrames++; if (restFrames > 25) { reset(); restFrames = 0; } }
    else restFrames = 0;
    if (inFlight && (x + SIZE < -100 || x > W + 100 || y > H + 200)) reset();
  }

  function step() {
    if (aiming) {
      aimAngle += aimDir * AIM_SPEED;
      if (aimAngle > AIM_MAX) { aimAngle = AIM_MAX; aimDir = -1; }
      if (aimAngle < AIM_MIN) { aimAngle = AIM_MIN; aimDir =  1; }
    }
    var prevY = y;
    if (inFlight) {
      vy += GRAVITY; vx *= AIR; vy *= AIR; clampV();
      x += vx; y += vy; rot += vrot; vrot *= 0.985;
      var W = window.innerWidth, H = window.innerHeight;
      if (x < 0) { x = 0; vx = -vx * BOUNCE_WALL; vrot = vx * SPIN; }
      else if (x + SIZE > W) { x = W - SIZE; vx = -vx * BOUNCE_WALL; vrot = vx * SPIN; }
      if (y < 0) { y = 0; vy = -vy * BOUNCE_WALL; }
      if (y + SIZE > H) {
        y = H - SIZE;
        if (Math.abs(vy) < 1.0) vy = 0; else vy = -vy * BOUNCE_FLOOR;
        vx *= GND_FRICTION; vrot = vx * SPIN * 3;
        if (Math.abs(vx) < 0.3) vx = 0;
      }
      if (collideRect(board)) touchedHoopSinceShot = true;
      var bxC = x + RADIUS, byC = y + RADIUS;
      var inOpening = bxC > scoreZone.x1 && bxC < scoreZone.x2;
      var fallingThrough = vy > 0 && byC < scoreZone.y + RADIUS * 0.6 && inOpening;
      if (!fallingThrough) {
        if (collideCircle(rimLeft))  touchedHoopSinceShot = true;
        if (collideCircle(rimRight)) touchedHoopSinceShot = true;
      }
      checkScore(prevY);
      maybeReset();
    }
    render();
    requestAnimationFrame(step);
  }

  ball.addEventListener('click', shoot);
  ball.addEventListener('touchstart', function (e) { e.preventDefault(); shoot(); }, { passive: false });
  window.addEventListener('keydown', function (e) {
    if (e.code === 'Space') { e.preventDefault(); shoot(); }
  });
  window.addEventListener('resize', function () { layout(); if (!inFlight) reset(); });

  layout(); reset(); step();
})();
